@r1.t w.request.target request=$r1 family=drawn mode=existing determiner=possessive fill=context sort=avatar
@r1.l1 w.request.lookup request=$r1 target=$r1.t key=thing from=page
@r1.u1 w.request.unread request=$r1 text="stay a robot" note=pref.avatar.figure value="a robot"
@r2 w.request.request act=save mood=do words="remember it for the next session too" predicate=remember
@r2.t w.request.target request=$r2 family=drawn mode=existing determiner=possessive fill=context sort=avatar
@r2.l1 w.request.lookup request=$r2 target=$r2.t key=thing from=page
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=preference.scope value="no matter which diagram or drawing I open" operator=eq phase=result
@r2.c1 w.request.constraint request=$r2 on=attribute attribute=preference.scope value="for the next session too" operator=eq phase=result

@r1 w.request.request act=change mood=do predicate=set words="Could you set my avatar to the robot figure"
@r1.t w.request.target request=$r1 family=drawn mode=existing determiner=possessive fill=context sort=avatar family_words=figure
@r1.l1 w.request.lookup request=$r1 target=$r1.t key=thing from=page
@r1.u1 w.request.unread request=$r1 text="the robot figure" note=pref.avatar.figure value="the robot figure"
@f1 w.request.filler text="instead of asking me again"
@r2 w.request.request act=change mood=do words="keep that figure every time I start a new drawing" predicate=keep
@r2.t w.request.target request=$r2 family=drawn mode=existing determiner=possessive fill=context sort=avatar
@r2.l1 w.request.lookup request=$r2 target=$r2.t key=thing from=page
@r2.c1 w.request.constraint request=$r2 on=attribute attribute=drawn.keep value=look operator=eq phase=result words="keep that figure every time I start a new drawing"
@r2.c2 w.request.constraint request=$r2 on=attribute attribute=preference.scope value="every time I start a new drawing" operator=eq phase=result

@f1 w.request.filler text=want
@r1 w.request.request act=change mood=do words="my avatar should remain a robot figure" predicate=remain
